          finalizeTimer = null;
        }
      };

      const schedulePendingResult = () => {
        clearFinalizeTimer();
        finalizeTimer = setTimeout(() => {
          finalizeTimer = null;
          if (resultSent || compactionActive || !pendingResult) {
